/**
 * Analytics service for recording page views.
 *
 * This is a server-side module. It is intentionally side-effect-free to import;
 * the actual logging happens when `logPageView` is invoked, which should be
 * scheduled via Next.js `after()` so it does not block the response.
 */

type PageViewEvent = {
  path: string
  userAgent: string
  timestamp: string
}

/**
 * Sends a page-view event to the analytics service.
 *
 * Returns a promise so it can be awaited (or fire-and-forget) from an `after`
 * callback. Failures are caught and logged so analytics errors never surface
 * to the user.
 */
export async function logPageView(event: PageViewEvent): Promise<void> {
  try {
    // In a real app this would POST to an analytics endpoint.
    // We log to the server console as a stand-in for the external service.
    console.log('[analytics] page view', event)
  } catch (error) {
    // Never let analytics failures propagate to the user.
    console.error('[analytics] failed to log page view', error)
  }
}

