import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from './analytics'

export default async function Home() {
  // Read request-time data *before* calling `after`. In a Server Component,
  // request APIs like headers() cannot be used inside the `after` callback,
  // so we capture the values during render and close over them.
  const headersList = await headers()
  const userAgent = headersList.get('user-agent') || 'unknown'
  const path = headersList.get('x-path') || '/'

  // Schedule the analytics call to run after the response is sent to the
  // user. `after` does not block the response — the callback executes once
  // the response (or prerender) has finished.
  after(() => {
    logPageView({
      path,
      userAgent,
      timestamp: new Date().toISOString(),
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for stopping by — your visit has been counted.</p>
    </main>
  )
}

